//! Golden corpus replay for poker-ai.
//!
//! Reads tests/golden/ai/*.jsonl (generated by oracle/golden-ai.js from the
//! original JS v1.5.8 implementation) and replays every decision through the
//! Rust adapter. The first milestone records a baseline instead of gating:
//!
//! * hard signals: action, amount, rng_calls (exact match counts)
//! * numeric   : equity mean / sample count vs the JS trace
//! * boundary  : mismatches are reported with their JS trace top-2 utility gap
//!
//! Set GOLDEN_AI_STRICT=1 to turn the baseline thresholds into hard asserts.

use std::collections::BTreeMap;
use std::fs;
use std::path::PathBuf;

use poker_ai::input::{ObservedAction, RawDecisionContext, ShowdownResult};
use poker_ai::{AIPlayer, ProfileSource, Style};
use poker_core::{Card, Variant};
use serde::Deserialize;

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct CardJson {
    rank: String,
    suit: String,
}

impl CardJson {
    fn card(&self) -> Card {
        poker_ai::input::card_vec::card_from_parts(&self.rank, &self.suit)
            .unwrap_or_else(|| panic!("bad card {}-{}", self.rank, self.suit))
    }
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct AiDesc {
    #[serde(rename = "type")]
    _ai_type: String,
    variant: String,
    style: String,
    #[serde(default)]
    seat_id: Option<usize>,
    name: String,
    profile_source: String,
    starting_stack: f64,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct AiState {
    #[serde(default)]
    hole_cards: Vec<CardJson>,
    stack: f64,
    chips_in_pot: f64,
    #[serde(default)]
    position: Option<usize>,
    num_players: usize,
    big_blind: f64,
    is_short_deck: bool,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "op", rename_all = "lowercase", rename_all_fields = "camelCase")]
enum ObserveOp {
    Observe {
        event: ObservedAction,
    },
    Showdown {
        seat_id: usize,
        info: ShowdownResult,
    },
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Expect {
    action: String,
    amount: u64,
    rng_calls: u64,
    #[serde(default)]
    trace: serde_json::Value,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct DecisionCase {
    id: String,
    category: String,
    tags: Vec<String>,
    ai: AiDesc,
    ai_state: AiState,
    observes: Vec<ObserveOp>,
    context: RawDecisionContext,
    expect: Expect,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "op", rename_all = "lowercase", rename_all_fields = "camelCase")]
#[allow(clippy::large_enum_variant)]
enum TrajectoryOp {
    Observe {
        event: ObservedAction,
    },
    Showdown {
        seat_id: usize,
        info: ShowdownResult,
    },
    Decide {
        ai_state: AiState,
        context: RawDecisionContext,
        expect: Expect,
    },
}

#[derive(Debug, Deserialize)]
struct Trajectory {
    id: String,
    tags: Vec<String>,
    ai: AiDesc,
    ops: Vec<TrajectoryOp>,
}

fn corpus_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden/ai")
}

fn read_jsonl<T: for<'de> Deserialize<'de>>(path: &PathBuf) -> Vec<T> {
    let text = fs::read_to_string(path).unwrap_or_else(|error| panic!("read {path:?}: {error}"));
    text.lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| {
            serde_json::from_str(line).unwrap_or_else(|error| panic!("parse line: {error}\n{line}"))
        })
        .collect()
}

fn style_of(ai: &AiDesc) -> Style {
    Style::from_name(&ai.style).unwrap_or_else(|| panic!("bad style {}", ai.style))
}

fn variant_of(ai: &AiDesc) -> Variant {
    if ai.variant == "shortdeck" {
        Variant::ShortDeck
    } else {
        Variant::Standard
    }
}

fn source_of(ai: &AiDesc) -> ProfileSource {
    match ai.profile_source.as_str() {
        "SD_STYLE_CONFIGS" => ProfileSource::ShortDeckLocalStyle,
        "STYLE_CONFIGS" if variant_of(ai) == Variant::ShortDeck => {
            ProfileSource::ShortDeckServerStyle
        }
        _ => ProfileSource::StandardStyle,
    }
}

fn seat_of(ai: &AiDesc, state: &AiState, context: &RawDecisionContext) -> usize {
    ai.seat_id
        .or(state.position)
        .or(context.hero_seat)
        .or(context.current_player_index)
        .unwrap_or(0)
}

fn build_player(ai: &AiDesc, seat_id: usize) -> AIPlayer {
    AIPlayer::new(
        &ai.name,
        style_of(ai),
        ai.starting_stack,
        seat_id,
        variant_of(ai),
        source_of(ai),
    )
}

fn apply_ai_state(player: &mut AIPlayer, state: &AiState, seat_id: usize) {
    let cards: Vec<Card> = state.hole_cards.iter().map(CardJson::card).collect();
    player.set_hole_cards(&cards);
    player.stack = state.stack;
    player.chips_in_pot = state.chips_in_pot;
    player.position = state.position.unwrap_or(seat_id);
    player.num_players = state.num_players;
    player.big_blind = state.big_blind;
    player.is_short_deck = state.is_short_deck;
}

#[derive(Debug, Clone)]
struct Sample {
    id: String,
    tags: Vec<String>,
    #[allow(dead_code)] // kept so failure reports can be grouped by corpus category
    category: String,
    expected_action: String,
    actual_action: String,
    expected_amount: u64,
    actual_amount: u64,
    expected_rng_calls: u64,
    actual_rng_calls: u64,
    expected_equity_mean: Option<f64>,
    actual_equity_mean: f64,
    expected_samples: Option<u64>,
    actual_samples: u64,
    js_top_gap: Option<f64>,
    expected_cfr: bool,
    actual_cfr: bool,
    cfr: CfrDiff,
}

fn trace_number(trace: &serde_json::Value, path: &[&str]) -> Option<f64> {
    let mut node = trace;
    for key in path {
        node = node.get(*key)?;
    }
    node.as_f64()
}

fn replay_case(case: &DecisionCase) -> Sample {
    let seat_id = seat_of(&case.ai, &case.ai_state, &case.context);
    let mut player = build_player(&case.ai, seat_id);
    apply_ai_state(&mut player, &case.ai_state, seat_id);
    for op in &case.observes {
        match op {
            ObserveOp::Observe { event } => player.record_opponent_action(event),
            ObserveOp::Showdown { seat_id, info } => player.record_showdown(*seat_id, info),
        }
    }
    let context = case.context.clone().normalize();
    let decision = player.decide(&context);
    let actual_action = decision.action.as_str().to_owned();
    let expected_equity_mean = trace_number(&case.expect.trace, &["equity", "mean"]);
    let expected_samples =
        trace_number(&case.expect.trace, &["equity", "samples"]).map(|value| value as u64);
    let js_top_gap = js_candidate_gap(&case.expect.trace);
    Sample {
        id: case.id.clone(),
        tags: case.tags.clone(),
        category: case.category.clone(),
        expected_action: case.expect.action.clone(),
        actual_action,
        expected_amount: case.expect.amount,
        actual_amount: decision.amount,
        expected_rng_calls: case.expect.rng_calls,
        actual_rng_calls: decision.trace.rng_calls,
        expected_equity_mean,
        actual_equity_mean: decision.trace.equity.mean,
        expected_samples,
        actual_samples: decision.trace.equity.samples,
        js_top_gap,
        expected_cfr: case.expect.trace.get("riverSolver").is_some(),
        actual_cfr: decision.trace.river_solver.is_some(),
        cfr: river_diff(&case.expect.trace, decision.trace.river_solver.as_ref()),
    }
}

fn river_diff(
    expected_trace: &serde_json::Value,
    actual: Option<&poker_ai::input::RiverTrace>,
) -> CfrDiff {
    let Some(js) = expected_trace.get("riverSolver") else {
        return CfrDiff::default();
    };
    let Some(actual) = actual else {
        return CfrDiff::default();
    };
    let mut diff = CfrDiff {
        expected_checked: js.get("checkedBefore").and_then(serde_json::Value::as_bool),
        actual_checked: Some(actual.checked_before),
        ..CfrDiff::default()
    };
    let js_actions: Vec<String> = js
        .get("policy")
        .and_then(|policy| policy.get("actions"))
        .and_then(serde_json::Value::as_array)
        .map(|actions| {
            actions
                .iter()
                .filter_map(|action| action.as_str().map(str::to_owned))
                .collect()
        })
        .unwrap_or_default();
    diff.policy_actions_equal = Some(js_actions == actual.policy.actions);
    diff.expected_policy = Some(js_actions);
    let js_probabilities: Vec<f64> = js
        .get("policy")
        .and_then(|policy| policy.get("probabilities"))
        .and_then(serde_json::Value::as_array)
        .map(|values| {
            values
                .iter()
                .filter_map(serde_json::Value::as_f64)
                .collect()
        })
        .unwrap_or_default();
    if js_probabilities.len() == actual.policy.probabilities.len() {
        let max = js_probabilities
            .iter()
            .zip(actual.policy.probabilities.iter())
            .map(|(a, b)| (a - b).abs())
            .fold(0.0_f64, f64::max);
        diff.policy_prob_diff = Some(max);
    }
    diff
}

#[derive(Clone, Debug, Default)]
struct CfrDiff {
    expected_policy: Option<Vec<String>>,
    policy_prob_diff: Option<f64>,
    expected_checked: Option<bool>,
    actual_checked: Option<bool>,
    policy_actions_equal: Option<bool>,
}

fn js_candidate_gap(trace: &serde_json::Value) -> Option<f64> {
    let candidates = trace.get("candidates")?.as_array()?;
    let first = candidates.first()?.get("utility")?.as_f64()?;
    let second = candidates
        .get(1)
        .and_then(|candidate| candidate.get("utility"))
        .and_then(serde_json::Value::as_f64);
    Some(second.map_or(f64::INFINITY, |second| first - second))
}

fn replay_trajectory(trajectory: &Trajectory) -> Vec<Sample> {
    let first_state = trajectory.ops.iter().find_map(|op| match op {
        TrajectoryOp::Decide { ai_state, .. } => Some(ai_state),
        _ => None,
    });
    let first_context = trajectory.ops.iter().find_map(|op| match op {
        TrajectoryOp::Decide { context, .. } => Some(context),
        _ => None,
    });
    let mut player = build_player(
        &trajectory.ai,
        seat_of(
            &trajectory.ai,
            first_state.unwrap_or_else(|| panic!("trajectory without decide: {}", trajectory.id)),
            first_context.unwrap_or_else(|| panic!("trajectory without decide: {}", trajectory.id)),
        ),
    );
    let mut out = Vec::new();
    for (index, op) in trajectory.ops.iter().enumerate() {
        match op {
            TrajectoryOp::Observe { event } => player.record_opponent_action(event),
            TrajectoryOp::Showdown { seat_id, info } => player.record_showdown(*seat_id, info),
            TrajectoryOp::Decide {
                ai_state,
                context,
                expect,
            } => {
                let seat = player.seat_id;
                apply_ai_state(&mut player, ai_state, seat);
                let normalized = context.clone().normalize();
                let decision = player.decide(&normalized);
                out.push(Sample {
                    id: format!("{}-step{index}", trajectory.id),
                    tags: trajectory.tags.clone(),
                    category: "trajectory".to_owned(),
                    expected_action: expect.action.clone(),
                    actual_action: decision.action.as_str().to_owned(),
                    expected_amount: expect.amount,
                    actual_amount: decision.amount,
                    expected_rng_calls: expect.rng_calls,
                    actual_rng_calls: decision.trace.rng_calls,
                    expected_equity_mean: trace_number(&expect.trace, &["equity", "mean"]),
                    actual_equity_mean: decision.trace.equity.mean,
                    expected_samples: trace_number(&expect.trace, &["equity", "samples"])
                        .map(|value| value as u64),
                    actual_samples: decision.trace.equity.samples,
                    js_top_gap: js_candidate_gap(&expect.trace),
                    expected_cfr: expect.trace.get("riverSolver").is_some(),
                    actual_cfr: decision.trace.river_solver.is_some(),
                    cfr: river_diff(&expect.trace, decision.trace.river_solver.as_ref()),
                });
            }
        }
    }
    out
}

fn load_cases() -> Vec<DecisionCase> {
    let dir = corpus_dir();
    let mut cases = Vec::new();
    for file in [
        "decisions-standard-target.jsonl",
        "decisions-standard-general.jsonl",
        "decisions-shortdeck.jsonl",
        "decisions-synthetic.jsonl",
    ] {
        cases.extend(read_jsonl::<DecisionCase>(&dir.join(file)));
    }
    cases
}

fn load_trajectories() -> Vec<Trajectory> {
    read_jsonl::<Trajectory>(&corpus_dir().join("trajectories.jsonl"))
}

fn summarize(samples: &[Sample], label: &str) {
    let total = samples.len();
    let action_hits = samples
        .iter()
        .filter(|sample| sample.expected_action == sample.actual_action)
        .count();
    let amount_hits = samples
        .iter()
        .filter(|sample| {
            sample.expected_action == sample.actual_action
                && sample.expected_amount == sample.actual_amount
        })
        .count();
    let rng_hits = samples
        .iter()
        .filter(|sample| sample.expected_rng_calls == sample.actual_rng_calls)
        .count();
    let sample_hits = samples
        .iter()
        .filter(|sample| sample.expected_samples == Some(sample.actual_samples))
        .count();
    let numeric_close = samples
        .iter()
        .filter(|sample| {
            sample
                .expected_equity_mean
                .is_some_and(|expected| (expected - sample.actual_equity_mean).abs() <= 1e-6)
        })
        .count();
    let expected_cfr = samples.iter().filter(|sample| sample.expected_cfr).count();
    let actual_cfr = samples.iter().filter(|sample| sample.actual_cfr).count();
    let cfr_matched = samples
        .iter()
        .filter(|sample| sample.expected_cfr && sample.actual_cfr)
        .count();
    let mut cfr_missing: Vec<&Sample> = samples
        .iter()
        .filter(|sample| sample.expected_cfr && !sample.actual_cfr)
        .collect();
    cfr_missing.sort_by_key(|sample| sample.id.clone());
    println!("river CFR: expected={expected_cfr} actual={actual_cfr} matched={cfr_matched}");
    for sample in cfr_missing.iter().take(8) {
        println!("  cfr missing: {}", sample.id);
    }
    println!("-- CFR case details --");
    for sample in samples.iter().filter(|sample| sample.expected_cfr).take(25) {
        println!(
            "  {} | exp {} {} -> act {} {} | rng {}/{} | actions_eq {:?} | prob_diff {:?} | checked {}/{:?} | js_gap {:?}",
            sample.id,
            sample.expected_action,
            sample.expected_amount,
            sample.actual_action,
            sample.actual_amount,
            sample.expected_rng_calls,
            sample.actual_rng_calls,
            sample.cfr.policy_actions_equal,
            sample.cfr.policy_prob_diff,
            sample
                .cfr
                .actual_checked
                .map_or("?".to_owned(), |value| value.to_string()),
            sample.cfr.expected_checked,
            sample.js_top_gap,
        );
    }
    let boundaries = samples
        .iter()
        .filter(|sample| {
            sample.expected_action != sample.actual_action
                && sample.js_top_gap.is_some_and(|gap| gap < 1e-6)
        })
        .count();
    println!("\n== {label}: {total} decisions ==");
    println!(
        "action exact     : {action_hits}/{total} ({:.1}%)",
        percent(action_hits, total)
    );
    println!(
        "amount exact     : {amount_hits}/{total} ({:.1}%)",
        percent(amount_hits, total)
    );
    println!(
        "rng_calls exact  : {rng_hits}/{total} ({:.1}%)",
        percent(rng_hits, total)
    );
    println!(
        "equity samples   : {sample_hits}/{total} ({:.1}%)",
        percent(sample_hits, total)
    );
    println!(
        "equity mean 1e-6 : {numeric_close}/{total} ({:.1}%)",
        percent(numeric_close, total)
    );
    println!("boundary (js gap<1e-6): {boundaries}");

    let mut groups: BTreeMap<String, (usize, usize)> = BTreeMap::new();
    for sample in samples {
        for tag in &sample.tags {
            let entry = groups.entry(tag.clone()).or_insert((0, 0));
            entry.1 += 1;
            if sample.expected_action == sample.actual_action {
                entry.0 += 1;
            }
        }
    }
    let mut rows: Vec<_> = groups
        .into_iter()
        .filter(|(_, (_, total))| *total >= 5)
        .collect();
    rows.sort_by_key(|(_, (_, total))| std::cmp::Reverse(*total));
    println!("-- action match by tag (n>=5) --");
    for (tag, (hits, total)) in rows.iter().take(24) {
        println!(
            "  {tag:<28} {hits:>4}/{total:<4} ({:.1}%)",
            percent(*hits, *total)
        );
    }

    let mut mismatches: Vec<&Sample> = samples
        .iter()
        .filter(|sample| sample.expected_action != sample.actual_action)
        .collect();
    mismatches.sort_by_key(|sample| sample.id.clone());
    println!(
        "-- first 20 mismatches (id | expected -> actual | amount exp/act | rng exp/act | samples exp/act | js-gap) --"
    );
    for sample in mismatches.iter().take(20) {
        println!(
            "  {} | {} -> {} | {}/{} | {}/{} | {:?}/{} | {:?}",
            sample.id,
            sample.expected_action,
            sample.actual_action,
            sample.expected_amount,
            sample.actual_amount,
            sample.expected_rng_calls,
            sample.actual_rng_calls,
            sample.expected_samples,
            sample.actual_samples,
            sample.js_top_gap,
        );
    }
}

fn percent(part: usize, total: usize) -> f64 {
    if total == 0 {
        0.0
    } else {
        part as f64 / total as f64 * 100.0
    }
}

#[test]
fn golden_decisions_baseline() {
    let cases = load_cases();
    assert_eq!(
        cases.len(),
        262,
        "expected the frozen 262-case decision corpus"
    );
    let samples: Vec<Sample> = cases.iter().map(replay_case).collect();
    summarize(&samples, "decision corpus");
    let trajectories = load_trajectories();
    let mut trajectory_samples = Vec::new();
    for trajectory in &trajectories {
        if trajectory.tags.iter().any(|tag| tag == "shortdeck") {
            continue;
        }
        trajectory_samples.extend(replay_trajectory(trajectory));
    }
    summarize(&trajectory_samples, "standard trajectories");

    if std::env::var("GOLDEN_AI_STRICT").as_deref() == Ok("1") {
        let hits = samples
            .iter()
            .filter(|sample| sample.expected_action == sample.actual_action)
            .count();
        assert!(
            percent(hits, samples.len()) >= 95.0,
            "action agreement below 95% (got {:.1}%)",
            percent(hits, samples.len())
        );
    }
}
